// MARK: - Match-3 game

enum Special { case none, stripedH, stripedV, bomb }

struct Pos: Hashable {
    let c: Int
    let r: Int
}

struct Run {
    var cells: [Pos]
    var horizontal: Bool
}

final class Tile {
    var kind: Int          // 0...5 = photo, 6 = color bomb
    var special: Special
    var node: SKNode

    init(kind: Int, special: Special, node: SKNode) {
        self.kind = kind
        self.special = special
        self.node = node
    }
}

final class MatchScene: SKScene {
    static func make() -> MatchScene {
        let s = MatchScene(size: UIScreen.main.bounds.size)
        s.scaleMode = .aspectFill
        return s
    }

    let cols = 8
    let rows = 8
    var cell: CGFloat = 44
    var x0: CGFloat = 0
    var y0: CGFloat = 0

    var grid: [[Tile?]] = []
    var board = SKNode()
    var faceTex: [SKTexture] = []
    var stripedTex: SKTexture!
    var bombTex: SKTexture!

    let kindColors: [UIColor] = [
        UIColor(red: 0.90, green: 0.25, blue: 0.30, alpha: 1),
        UIColor(red: 0.95, green: 0.60, blue: 0.15, alpha: 1),
        UIColor(red: 0.95, green: 0.85, blue: 0.20, alpha: 1),
        UIColor(red: 0.30, green: 0.75, blue: 0.35, alpha: 1),
        UIColor(red: 0.25, green: 0.55, blue: 0.95, alpha: 1),
        UIColor(red: 0.65, green: 0.35, blue: 0.85, alpha: 1)
    ]

    var score = 0
    var moves = 25
    var busy = false
    var overShown = false
    var overDate = Date()
    var overlay: SKNode?
    var scoreLabel: SKLabelNode!
    var movesLabel: SKLabelNode!
    var selected: Pos?
    var selRing: SKShapeNode?
    var startPos: Pos?
    var startPoint = CGPoint.zero
    var didSetup = false

    // MARK: setup

    override func didMove(to view: SKView) {
        if !didSetup {
            didSetup = true
            setup()
        }
    }

    func setup() {
        backgroundColor = UIColor(red: 0.14, green: 0.07, blue: 0.24, alpha: 1)
        cell = floor((size.width - 16) / CGFloat(cols))
        x0 = (size.width - CGFloat(cols) * cell) / 2
        y0 = (size.height - CGFloat(rows) * cell) / 2 - 10

        let back = SKSpriteNode(color: UIColor(white: 1, alpha: 0.10),
                                size: CGSize(width: CGFloat(cols) * cell + 12, height: CGFloat(rows) * cell + 12))
        back.position = CGPoint(x: size.width / 2, y: y0 + CGFloat(rows) * cell / 2)
        back.zPosition = -10
        addChild(back)

        board.zPosition = 0
        addChild(board)

        scoreLabel = makeLabel("Score: 0", 28, UIColor.white)
        scoreLabel.position = CGPoint(x: size.width / 2, y: size.height - 100)
        scoreLabel.zPosition = 100
        addChild(scoreLabel)

        movesLabel = makeLabel("Moves: 25", 20, UIColor.yellow)
        movesLabel.position = CGPoint(x: size.width / 2, y: size.height - 132)
        movesLabel.zPosition = 100
        addChild(movesLabel)

        loadTextures()
        newGame()
    }

    func loadTextures() {
        faceTex = (0..<6).map { SKTexture(image: Store.load($0)) }
        stripedTex = SKTexture(image: Store.load(6))
        bombTex = SKTexture(image: Store.load(7))
    }

    func reloadImages() {
        loadTextures()
        newGame()
    }

    func newGame() {
        removeAllActions()
        board.removeAllActions()
        board.removeAllChildren()
        board.position = CGPoint.zero
        overlay?.removeFromParent()
        overlay = nil
        selRing = nil
        selected = nil
        startPos = nil
        score = 0
        moves = 25
        busy = false
        overShown = false
        fillBoard()
        seedBombSetup()
        updateHUD()
    }

    func updateHUD() {
        scoreLabel.text = "Score: \(score)"
        movesLabel.text = "Moves: \(moves)"
    }

    func after(_ t: TimeInterval, _ f: @escaping () -> Void) {
        run(SKAction.sequence([SKAction.wait(forDuration: t), SKAction.run(f)]))
    }

    func pos(_ c: Int, _ r: Int) -> CGPoint {
        return CGPoint(x: x0 + (CGFloat(c) + 0.5) * cell, y: y0 + (CGFloat(r) + 0.5) * cell)
    }

    func posAt(_ p: CGPoint) -> Pos? {
        let c = Int(floor((p.x - x0) / cell))
        let r = Int(floor((p.y - y0) / cell))
        if c >= 0 && c < cols && r >= 0 && r < rows {
            return Pos(c: c, r: r)
        }
        return nil
    }

    // MARK: tiles

    func makeTileNode(kind: Int, special: Special) -> SKNode {
        let w = cell - 6
        let n = SKNode()
        let bgColor = kind >= 6 ? UIColor(red: 0.20, green: 0.10, blue: 0.30, alpha: 1) : kindColors[kind]
        let bg = SKShapeNode(rectOf: CGSize(width: w, height: w), cornerRadius: w * 0.22)
        bg.fillColor = bgColor
        bg.strokeColor = UIColor(white: 1, alpha: 0.7)
        bg.lineWidth = 2
        n.addChild(bg)

        let tex: SKTexture
        if special == .bomb {
            tex = bombTex
        } else if special == .none {
            tex = faceTex[kind]
        } else {
            tex = stripedTex
        }
        let face = SKSpriteNode(texture: tex, size: CGSize(width: w * 0.84, height: w * 0.84))
        n.addChild(face)

        if special == .stripedH {
            for i in -1...1 {
                let s = SKSpriteNode(color: UIColor(white: 1, alpha: 0.7), size: CGSize(width: w * 0.9, height: 3))
                s.position = CGPoint(x: 0, y: CGFloat(i) * w * 0.28)
                n.addChild(s)
            }
        } else if special == .stripedV {
            for i in -1...1 {
                let s = SKSpriteNode(color: UIColor(white: 1, alpha: 0.7), size: CGSize(width: 3, height: w * 0.9))
                s.position = CGPoint(x: CGFloat(i) * w * 0.28, y: 0)
                n.addChild(s)
            }
        } else if special == .bomb {
            let ring = SKShapeNode(circleOfRadius: w * 0.55)
            ring.strokeColor = UIColor.orange
            ring.lineWidth = 3
            ring.fillColor = UIColor.clear
            n.addChild(ring)
            let pulse = SKAction.sequence([SKAction.scale(to: 1.08, duration: 0.45), SKAction.scale(to: 0.94, duration: 0.45)])
            n.run(SKAction.repeatForever(pulse))
        }
        return n
    }

    @discardableResult
    func addTile(_ c: Int, _ r: Int, kind: Int, special: Special) -> Tile {
        let n = makeTileNode(kind: kind, special: special)
        n.position = pos(c, r)
        n.zPosition = 1
        board.addChild(n)
        let t = Tile(kind: kind, special: special, node: n)
        grid[c][r] = t
        return t
    }

    func wouldMatch(_ c: Int, _ r: Int, _ k: Int) -> Bool {
        if c >= 2, let a = grid[c - 1][r], let b = grid[c - 2][r], a.kind == k, b.kind == k { return true }
        if r >= 2, let a = grid[c][r - 1], let b = grid[c][r - 2], a.kind == k, b.kind == k { return true }
        return false
    }

    func randomKind(_ c: Int, _ r: Int) -> Int {
        var k = Int.random(in: 0..<6)
        var tries = 0
        while tries < 30 && wouldMatch(c, r, k) {
            k = Int.random(in: 0..<6)
            tries += 1
        }
        return k
    }

    func fillBoard() {
        var attempts = 0
        repeat {
            board.removeAllChildren()
            selRing = nil
            selected = nil
            grid = Array(repeating: Array<Tile?>(repeating: nil, count: rows), count: cols)
            for c in 0..<cols {
                for r in 0..<rows {
                    addTile(c, r, kind: randomKind(c, r), special: .none)
                }
            }
            attempts += 1
        } while !hasPossibleMove() && attempts < 30
    }

    // MARK: matching

    func findRuns() -> [Run] {
        var runs: [Run] = []
        for r in 0..<rows {
            var c = 0
            while c < cols {
                guard let t = grid[c][r], t.kind < 6 else {
                    c += 1
                    continue
                }
                var e = c + 1
                while e < cols, let u = grid[e][r], u.kind == t.kind {
                    e += 1
                }
                if e - c >= 3 {
                    var cells: [Pos] = []
                    for x in c..<e { cells.append(Pos(c: x, r: r)) }
                    runs.append(Run(cells: cells, horizontal: true))
                }
                c = e
            }
        }
        for c in 0..<cols {
            var r = 0
            while r < rows {
                guard let t = grid[c][r], t.kind < 6 else {
                    r += 1
                    continue
                }
                var e = r + 1
                while e < rows, let u = grid[c][e], u.kind == t.kind {
                    e += 1
                }
                if e - r >= 3 {
                    var cells: [Pos] = []
                    for y in r..<e { cells.append(Pos(c: c, r: y)) }
                    runs.append(Run(cells: cells, horizontal: false))
                }
                r = e
            }
        }
        return runs
    }

    func testSwap(_ c1: Int, _ r1: Int, _ c2: Int, _ r2: Int) -> Bool {
        let t1 = grid[c1][r1]
        let t2 = grid[c2][r2]
        grid[c1][r1] = t2
        grid[c2][r2] = t1
        let ok = !findRuns().isEmpty
        grid[c1][r1] = t1
        grid[c2][r2] = t2
        return ok
    }

    func hasPossibleMove() -> Bool {
        for c in 0..<cols {
            for r in 0..<rows {
                if let t = grid[c][r], t.special == .bomb { return true }
                if c + 1 < cols && testSwap(c, r, c + 1, r) { return true }
                if r + 1 < rows && testSwap(c, r, c, r + 1) { return true }
            }
        }
        return false
    }

    // MARK: guaranteed 5-match setup

    func setKind(_ c: Int, _ r: Int, _ k: Int) {
        guard let t = grid[c][r], t.special == .none else { return }
        let old = t.node
        let n = makeTileNode(kind: k, special: .none)
        n.position = old.position
        n.zPosition = 1
        board.addChild(n)
        old.removeFromParent()
        t.node = n
        t.kind = k
    }

    // puts "X X _ X X" in a row with an X above/below the gap, so one swap makes 5 in a row
    func seedBombSetup() {
        for _ in 0..<15 {
            let r = Int.random(in: 1..<(rows - 1))
            let c = Int.random(in: 0...(cols - 5))
            let k = Int.random(in: 0..<6)
            var m = Int.random(in: 0..<6)
            while m == k { m = Int.random(in: 0..<6) }
            let rr = Bool.random() ? r + 1 : r - 1
            let cells: [Pos] = [
                Pos(c: c, r: r), Pos(c: c + 1, r: r), Pos(c: c + 2, r: r),
                Pos(c: c + 3, r: r), Pos(c: c + 4, r: r), Pos(c: c + 2, r: rr)
            ]
            var ok = true
            var saved: [Int] = []
            for p in cells {
                if let t = grid[p.c][p.r], t.special == .none {
                    saved.append(t.kind)
                } else {
                    ok = false
                    break
                }
            }
            if !ok { continue }
            let newKinds: [Int] = [k, k, m, k, k, k]
            for (i, p) in cells.enumerated() { setKind(p.c, p.r, newKinds[i]) }
            if findRuns().isEmpty { return }
            for (i, p) in cells.enumerated() { setKind(p.c, p.r, saved[i]) }
        }
    }

    // MARK: swapping

    func trySwap(_ a: Pos, _ b: Pos) {
        if busy || overShown || moves <= 0 { return }
        guard let ta = grid[a.c][a.r], let tb = grid[b.c][b.r] else { return }
        busy = true
        grid[a.c][a.r] = tb
        grid[b.c][b.r] = ta
        ta.node.run(SKAction.move(to: pos(b.c, b.r), duration: 0.15))
        tb.node.run(SKAction.move(to: pos(a.c, a.r), duration: 0.15))
        after(0.18) {
            if ta.special == .bomb || tb.special == .bomb {
                self.moves -= 1
                self.updateHUD()
                var clear = Set<Pos>()
                clear.insert(a)
                clear.insert(b)
                if ta.special == .bomb && tb.special == .bomb {
                    for c in 0..<self.cols {
                        for r in 0..<self.rows {
                            clear.insert(Pos(c: c, r: r))
                        }
                    }
                } else {
                    let target = (ta.special == .bomb) ? tb.kind : ta.kind
                    for c in 0..<self.cols {
                        for r in 0..<self.rows {
                            if let t = self.grid[c][r], t.kind == target {
                                clear.insert(Pos(c: c, r: r))
                            }
                        }
                    }
                }
                let bp = (ta.special == .bomb) ? b : a
                self.explosion(at: self.pos(bp.c, bp.r))
                self.executeClear(clear, creations: [:], combo: 1)
                return
            }
            if self.findRuns().isEmpty {
                self.grid[a.c][a.r] = ta
                self.grid[b.c][b.r] = tb
                ta.node.run(SKAction.move(to: self.pos(a.c, a.r), duration: 0.15))
                tb.node.run(SKAction.move(to: self.pos(b.c, b.r), duration: 0.15))
                self.after(0.18) {
                    self.busy = false
                }
            } else {
                self.moves -= 1
                self.updateHUD()
                self.processMatches(swapA: a, swapB: b, combo: 1)
            }
        }
    }

    func processMatches(swapA: Pos?, swapB: Pos?, combo: Int) {
        let runs = findRuns()
        if runs.isEmpty {
            finishTurn()
            return
        }
        var clear = Set<Pos>()
        var creations: [Pos: Special] = [:]
        for run in runs {
            for p in run.cells { clear.insert(p) }
            if run.cells.count >= 4 {
                var spot = run.cells[run.cells.count / 2]
                if let a = swapA, run.cells.contains(a) {
                    spot = a
                } else if let b = swapB, run.cells.contains(b) {
                    spot = b
                }
                let sp: Special = run.cells.count >= 5 ? .bomb : (run.horizontal ? .stripedV : .stripedH)
                if creations[spot] != .bomb {
                    creations[spot] = sp
                }
            }
        }
        for (p, _) in creations {
            clear.remove(p)
        }
        executeClear(clear, creations: creations, combo: combo)
    }

    func executeClear(_ initial: Set<Pos>, creations: [Pos: Special], combo: Int) {
        var clear = initial
        var queue = Array(initial)
        var idx = 0
        while idx < queue.count {
            let p = queue[idx]
            idx += 1
            guard let t = grid[p.c][p.r] else { continue }
            var extra: [Pos] = []
            if t.special == .stripedH {
                lineFlash(horizontal: true, p)
                for c in 0..<cols { extra.append(Pos(c: c, r: p.r)) }
            } else if t.special == .stripedV {
                lineFlash(horizontal: false, p)
                for r in 0..<rows { extra.append(Pos(c: p.c, r: r)) }
            }
            for e in extra {
                if !clear.contains(e) && creations[e] == nil {
                    clear.insert(e)
                    queue.append(e)
                }
            }
        }

        var count = 0
        for p in clear {
            guard let t = grid[p.c][p.r] else { continue }
            grid[p.c][p.r] = nil
            count += 1
            let n = t.node
            n.removeAllActions()
            n.run(SKAction.sequence([
                SKAction.group([SKAction.scale(to: 0.1, duration: 0.18), SKAction.fadeOut(withDuration: 0.18)]),
                SKAction.removeFromParent()
            ]))
            burst(at: pos(p.c, p.r), color: kindColors[min(t.kind, 5)], count: 6, dist: 34)
        }
        for (p, sp) in creations {
            guard let t = grid[p.c][p.r] else { continue }
            convert(t, to: sp)
        }
        score += count * 10 * combo
        updateHUD()

        after(0.32) {
            let d = self.collapseAndRefill()
            self.after(d + 0.05) {
                self.processMatches(swapA: nil, swapB: nil, combo: combo + 1)
            }
        }
    }

    func convert(_ t: Tile, to sp: Special) {
        let old = t.node
        let newKind = (sp == .bomb) ? 6 : t.kind
        let n = makeTileNode(kind: newKind, special: sp)
        n.position = old.position
        n.zPosition = 5
        board.addChild(n)
        old.removeFromParent()
        t.node = n
        t.special = sp
        t.kind = newKind
        n.setScale(0.2)
        n.run(SKAction.sequence([SKAction.scale(to: 1.25, duration: 0.15), SKAction.scale(to: 1.0, duration: 0.1)]))
        if sp == .bomb {
            explosion(at: n.position)
        }
    }

    func collapseAndRefill() -> TimeInterval {
        var maxDur: TimeInterval = 0.1
        for c in 0..<cols {
            var write = 0
            for r in 0..<rows {
                if let t = grid[c][r] {
                    if r != write {
                        grid[c][write] = t
                        grid[c][r] = nil
                        let dur = 0.1 + 0.06 * Double(r - write)
                        let mv = SKAction.move(to: pos(c, write), duration: dur)
                        mv.timingMode = .easeIn
                        t.node.run(mv)
                        if dur > maxDur { maxDur = dur }
                    }
                    write += 1
                }
            }
            var spawn = 0
            if write < rows {
                for r in write..<rows {
                    let t = addTile(c, r, kind: Int.random(in: 0..<6), special: .none)
                    let startRow = rows + spawn
                    spawn += 1
                    t.node.position = pos(c, startRow)
                    let dur = 0.1 + 0.06 * Double(startRow - r)
                    let mv = SKAction.move(to: pos(c, r), duration: dur)
                    mv.timingMode = .easeIn
                    t.node.run(mv)
                    if dur > maxDur { maxDur = dur }
                }
            }
        }
        return maxDur
    }

    func finishTurn() {
        board.position = CGPoint.zero
        if moves <= 0 {
            showGameOver()
            return
        }
        if !hasPossibleMove() {
            fillBoard()
            showToast("No moves left - shuffled!")
        }
        seedBombSetup()
        busy = false
    }

    // MARK: effects

    func burst(at p: CGPoint, color: UIColor, count: Int, dist: CGFloat) {
        for _ in 0..<count {
            let s = SKSpriteNode(color: color, size: CGSize(width: 6, height: 6))
            s.position = p
            s.zPosition = 50
            board.addChild(s)
            let ang = CGFloat.random(in: 0..<(2 * CGFloat.pi))
            let d = CGFloat.random(in: (dist * 0.5)...dist)
            let move = SKAction.moveBy(x: cos(ang) * d, y: sin(ang) * d, duration: 0.3)
            s.run(SKAction.sequence([
                SKAction.group([move, SKAction.fadeOut(withDuration: 0.3)]),
                SKAction.removeFromParent()
            ]))
        }
    }

    func lineFlash(horizontal: Bool, _ p: Pos) {
        let center = pos(p.c, p.r)
        let s: SKSpriteNode
        if horizontal {
            s = SKSpriteNode(color: UIColor.white, size: CGSize(width: CGFloat(cols) * cell, height: cell * 0.5))
            s.position = CGPoint(x: size.width / 2, y: center.y)
        } else {
            s = SKSpriteNode(color: UIColor.white, size: CGSize(width: cell * 0.5, height: CGFloat(rows) * cell))
            s.position = CGPoint(x: center.x, y: y0 + CGFloat(rows) * cell / 2)
        }
        s.zPosition = 55
        s.alpha = 0.9
        board.addChild(s)
        s.run(SKAction.sequence([SKAction.fadeOut(withDuration: 0.35), SKAction.removeFromParent()]))
    }

    func explosion(at p: CGPoint) {
        UIImpactFeedbackGenerator(style: .heavy).impactOccurred()

        let ring = SKShapeNode(circleOfRadius: 20)
        ring.position = p
        ring.zPosition = 60
        ring.strokeColor = UIColor.orange
        ring.lineWidth = 8
        ring.fillColor = UIColor(red: 1.0, green: 0.8, blue: 0.2, alpha: 0.6)
        board.addChild(ring)
        ring.run(SKAction.sequence([
            SKAction.group([SKAction.scale(to: 9, duration: 0.45), SKAction.fadeOut(withDuration: 0.45)]),
            SKAction.removeFromParent()
        ]))

        let fire: [UIColor] = [UIColor.red, UIColor.orange, UIColor.yellow, UIColor.white]
        for col in fire {
            burst(at: p, color: col, count: 8, dist: 150)
        }

        let boom = SKLabelNode(text: "💥")
        boom.fontSize = 60
        boom.position = CGPoint(x: p.x, y: p.y - 20)
        boom.zPosition = 65
        boom.setScale(0.3)
        board.addChild(boom)
        boom.run(SKAction.sequence([
            SKAction.group([SKAction.scale(to: 3.0, duration: 0.4), SKAction.fadeOut(withDuration: 0.4)]),
            SKAction.removeFromParent()
        ]))

        let flash = SKSpriteNode(color: UIColor.white, size: size)
        flash.position = CGPoint(x: size.width / 2, y: size.height / 2)
        flash.zPosition = 70
        flash.alpha = 0
        addChild(flash)
        flash.run(SKAction.sequence([
            SKAction.fadeAlpha(to: 0.7, duration: 0.05),
            SKAction.fadeOut(withDuration: 0.25),
            SKAction.removeFromParent()
        ]))

        board.run(SKAction.sequence([
            SKAction.moveBy(x: 10, y: 6, duration: 0.04),
            SKAction.moveBy(x: -20, y: -12, duration: 0.04),
            SKAction.moveBy(x: 20, y: 12, duration: 0.04),
            SKAction.moveBy(x: -10, y: -6, duration: 0.04)
        ]))
    }

    func showToast(_ text: String) {
        let l = makeLabel(text, 20, UIColor.white)
        l.position = CGPoint(x: size.width / 2, y: size.height * 0.80)
        l.zPosition = 150
        addChild(l)
        l.run(SKAction.sequence([SKAction.wait(forDuration: 1.2), SKAction.fadeOut(withDuration: 0.4), SKAction.removeFromParent()]))
    }

    // MARK: game over

    func showGameOver() {
        overShown = true
        overDate = Date()
        let best = max(score, UserDefaults.standard.integer(forKey: "bestMatch"))
        UserDefaults.standard.set(best, forKey: "bestMatch")

        let o = SKNode()
        o.zPosition = 200
        let dim = SKSpriteNode(color: UIColor(white: 0, alpha: 0.7), size: size)
        dim.position = CGPoint(x: size.width / 2, y: size.height / 2)
        o.addChild(dim)

        let t1 = makeLabel("OUT OF MOVES", 38, UIColor.white)
        t1.position = CGPoint(x: size.width / 2, y: size.height * 0.60)
        o.addChild(t1)
        let t2 = makeLabel("Score: \(score)", 28, UIColor.yellow)
        t2.position = CGPoint(x: size.width / 2, y: size.height * 0.54)
        o.addChild(t2)
        let t3 = makeLabel("Best: \(best)", 22, UIColor.white)
        t3.position = CGPoint(x: size.width / 2, y: size.height * 0.49)
        o.addChild(t3)
        let t4 = makeLabel("tap to play again", 20, UIColor.lightGray)
        t4.position = CGPoint(x: size.width / 2, y: size.height * 0.42)
        o.addChild(t4)

        addChild(o)
        overlay = o
    }

    // MARK: input

    func select(_ p: Pos) {
        clearSelection()
        selected = p
        let ring = SKShapeNode(rectOf: CGSize(width: cell - 2, height: cell - 2), cornerRadius: 10)
        ring.strokeColor = UIColor.white
        ring.lineWidth = 3
        ring.fillColor = UIColor.clear
        ring.position = pos(p.c, p.r)
        ring.zPosition = 20
        board.addChild(ring)
        selRing = ring
    }

    func clearSelection() {
        selRing?.removeFromParent()
        selRing = nil
        selected = nil
    }

    func isAdjacent(_ a: Pos, _ b: Pos) -> Bool {
        return abs(a.c - b.c) + abs(a.r - b.r) == 1
    }

    override func touchesBegan(_ touches: Set<UITouch>, with event: UIEvent?) {
        guard let touch = touches.first else { return }
        if overShown {
            if Date().timeIntervalSince(overDate) > 0.6 {
                newGame()
            }
            return
        }
        if busy { return }
        let p = touch.location(in: self)
        guard let tp = posAt(p) else { return }
        if let s = selected, isAdjacent(s, tp) {
            clearSelection()
            trySwap(s, tp)
            return
        }
        startPos = tp
        startPoint = p
        select(tp)
    }

    override func touchesMoved(_ touches: Set<UITouch>, with event: UIEvent?) {
        guard let sp = startPos, !busy, let touch = touches.first else { return }
        let p = touch.location(in: self)
        let dx = p.x - startPoint.x
        let dy = p.y - startPoint.y
        if max(abs(dx), abs(dy)) > cell * 0.45 {
            var target = sp
            if abs(dx) > abs(dy) {
                target = Pos(c: sp.c + (dx > 0 ? 1 : -1), r: sp.r)
            } else {
                target = Pos(c: sp.c, r: sp.r + (dy > 0 ? 1 : -1))
            }
            startPos = nil
            clearSelection()
            if target.c >= 0 && target.c < cols && target.r >= 0 && target.r < rows {
                trySwap(sp, target)
            }
        }
    }

    override func touchesEnded(_ touches: Set<UITouch>, with event: UIEvent?) {
        startPos = nil
    }
}

// MARK: - ============ DEAD SHOT : RDR2-style shooting range ============
// Real ballistics: bullet travel time, drag, gravity drop, wind drift, weapon sway,
// breath holding, recoil kick, Dead Eye slow-mo + mark & execute.

func shc(_ r: CGFloat, _ g: CGFloat, _ b: CGFloat, _ a: CGFloat = 1) -> UIColor {
    return UIColor(red: r, green: g, blue: b, alpha: a)
}

// MARK: Synth sound effects (no audio files needed)

final class ShSFX {
    static let shared = ShSFX()
    private let engine = AVAudioEngine()
    private var players: [AVAudioPlayerNode] = []
    private var idx = 0
    private var ready = false
    private let bShot: AVAudioPCMBuffer
    private let bGlass: AVAudioPCMBuffer
    private let bPing: AVAudioPCMBuffer
    private let bThud: AVAudioPCMBuffer
    private let bClick: AVAudioPCMBuffer
    private let bDirt: AVAudioPCMBuffer

    private static func make(_ fmt: AVAudioFormat, _ dur: Double, _ gen: (Double) -> Float) -> AVAudioPCMBuffer {
        let n = AVAudioFrameCount(dur * fmt.sampleRate)
        let b = AVAudioPCMBuffer(pcmFormat: fmt, frameCapacity: n)!
        b.frameLength = n
        let p = b.floatChannelData![0]
        for i in 0..<Int(n) {
            let v = gen(Double(i) / fmt.sampleRate)
            p[i] = max(-1, min(1, v))
        }
        return b
    }

    private init() {
        let fmt = AVAudioFormat(standardFormatWithSampleRate: 44100, channels: 1)!
        let twoPi = 2.0 * Double.pi

        var lp: Float = 0
        bShot = ShSFX.make(fmt, 1.2) { t in
            let n = Float.random(in: -1...1)
            lp += (n - lp) * 0.16
            let crack = n * Float(exp(-t * 90)) * 0.7
            let boom = lp * Float(exp(-t * 7)) * 1.7
            let thump = Float(sin(twoPi * 60 * t)) * Float(exp(-t * 15)) * 0.9
            let tail = lp * Float(exp(-t * 3.0)) * 0.55
            return crack + boom + thump + tail
        }

        var prev: Float = 0
        bGlass = ShSFX.make(fmt, 0.5) { t in
            let n = Float.random(in: -1...1)
            let h = n - prev
            prev = n
            let env = Float(exp(-t * 10))
            let tink = Float(sin(twoPi * (2800 + 900 * sin(t * 60)) * t)) * Float(exp(-t * 24)) * 0.25
            return h * 0.5 * env + tink
        }

        bPing = ShSFX.make(fmt, 0.7) { t in
            let a = Float(sin(twoPi * 1650 * t)) * Float(exp(-t * 7)) * 0.5
            let b = Float(sin(twoPi * 2480 * t)) * Float(exp(-t * 9)) * 0.3
            return a + b
        }

        bThud = ShSFX.make(fmt, 0.4) { t in
            let a = Float(sin(twoPi * 180 * t)) * Float(exp(-t * 22)) * 0.8
            let n = Float.random(in: -1...1) * Float(exp(-t * 70)) * 0.4
            let r = Float(sin(twoPi * 900 * t)) * Float(exp(-t * 14)) * 0.2
            return a + n + r
        }

        bClick = ShSFX.make(fmt, 0.06) { t in
            return Float.random(in: -1...1) * Float(exp(-t * 260)) * 0.7
        }

        var lp2: Float = 0
        bDirt = ShSFX.make(fmt, 0.2) { t in
            let n = Float.random(in: -1...1)
            lp2 += (n - lp2) * 0.2
            return lp2 * Float(exp(-t * 28)) * 0.9
        }

        let session = AVAudioSession.sharedInstance()
        try? session.setCategory(.ambient, options: [.mixWithOthers])
        try? session.setActive(true)
        for _ in 0..<6 {
            let p = AVAudioPlayerNode()
            engine.attach(p)
            engine.connect(p, to: engine.mainMixerNode, format: fmt)
            players.append(p)
        }
        do {
            try engine.start()
            ready = true
        } catch {
            ready = false
        }
    }

    private func play(_ b: AVAudioPCMBuffer, _ vol: Float) {
        guard ready else { return }
        if !engine.isRunning { try? engine.start() }
        let p = players[idx]
        idx = (idx + 1) % players.count
        p.volume = vol
        p.scheduleBuffer(b, at: nil, options: .interrupts, completionHandler: nil)
        if !p.isPlaying { p.play() }
    }

    func shot() { play(bShot, 1.0) }
    func glass(_ v: Float = 0.8) { play(bGlass, v) }
    func ping(_ v: Float = 0.8) { play(bPing, v) }
    func thud(_ v: Float = 0.8) { play(bThud, v) }
    func click() { play(bClick, 0.8) }
    func dirt(_ v: Float = 0.6) { play(bDirt, v) }
}

// MARK: Procedural art (all graphics drawn in code)

enum ShArt {
    static func img(_ size: CGSize, scale: CGFloat = 3, _ draw: (CGContext) -> Void) -> UIImage {
        let f = UIGraphicsImageRendererFormat()
        f.scale = scale
        f.opaque = false
        return UIGraphicsImageRenderer(size: size, format: f).image { draw($0.cgContext) }
    }

    static func lin(_ c: CGContext, _ cols: [UIColor], _ locs: [CGFloat], _ a: CGPoint, _ b: CGPoint) {
        guard let g = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(),
                                 colors: cols.map { $0.cgColor } as CFArray,
                                 locations: locs) else { return }
        c.drawLinearGradient(g, start: a, end: b, options: [.drawsBeforeStartLocation, .drawsAfterEndLocation])
    }

    static func rad(_ c: CGContext, _ cols: [UIColor], _ locs: [CGFloat], _ center: CGPoint, _ r0: CGFloat, _ r1: CGFloat) {
        guard let g = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(),
                                 colors: cols.map { $0.cgColor } as CFArray,
                                 locations: locs) else { return }
        c.drawRadialGradient(g, startCenter: center, startRadius: r0, endCenter: center, endRadius: r1,
                             options: [.drawsAfterEndLocation])
    }

    static let soft: SKTexture = {
        let im = img(CGSize(width: 128, height: 128), scale: 1) { c in
            rad(c, [shc(1, 1, 1, 1), shc(1, 1, 1, 0.5), shc(1, 1, 1, 0)], [0, 0.4, 1],
                CGPoint(x: 64, y: 64), 0, 64)
        }
        return SKTexture(image: im)
    }()

    static let shard: SKTexture = {
        let im = img(CGSize(width: 16, height: 16), scale: 2) { c in
            let p = UIBezierPath()
            p.move(to: CGPoint(x: 8, y: 1))
            p.addLine(to: CGPoint(x: 15, y: 14))
            p.addLine(to: CGPoint(x: 2, y: 11))
            p.close()
            shc(1, 1, 1).setFill()
            p.fill()
        }
        return SKTexture(image: im)
    }()

    static let flash: SKTexture = {
        let im = img(CGSize(width: 200, height: 200), scale: 2) { c in
            let ctr = CGPoint(x: 100, y: 100)
            let star = UIBezierPath()
            let n = 12
            for i in 0..<(n * 2) {
                let ang = CGFloat(i) * CGFloat.pi / CGFloat(n)
                var r: CGFloat = 18
                if i % 2 == 0 { r = (i % 4 == 0) ? 98 : 68 }
                let p = CGPoint(x: ctr.x + cos(ang) * r, y: ctr.y + sin(ang) * r)
                if i == 0 { star.move(to: p) } else { star.addLine(to: p) }
            }
            star.close()
            c.saveGState()
            star.addClip()
            rad(c, [shc(1, 1, 0.85, 1), shc(1, 0.75, 0.2, 0.95), shc(1, 0.35, 0, 0)], [0, 0.35, 1], ctr, 0, 98)
            c.restoreGState()
        }
        return SKTexture(image: im)
    }()

    static let bottle: SKTexture = {
        let im = img(CGSize(width: 40, height: 112)) { c in
            let p = UIBezierPath()
            p.move(to: CGPoint(x: 15, y: 2))
            p.addLine(to: CGPoint(x: 25, y: 2))
            p.addLine(to: CGPoint(x: 25, y: 9))
            p.addLine(to: CGPoint(x: 23.5, y: 12))
            p.addLine(to: CGPoint(x: 23.5, y: 40))
            p.addCurve(to: CGPoint(x: 35, y: 62), controlPoint1: CGPoint(x: 23.5, y: 50), controlPoint2: CGPoint(x: 35, y: 52))
            p.addLine(to: CGPoint(x: 35, y: 104))
            p.addQuadCurve(to: CGPoint(x: 31, y: 109), controlPoint: CGPoint(x: 35, y: 109))
            p.addLine(to: CGPoint(x: 9, y: 109))
            p.addQuadCurve(to: CGPoint(x: 5, y: 104), controlPoint: CGPoint(x: 5, y: 109))
            p.addLine(to: CGPoint(x: 5, y: 62))
            p.addCurve(to: CGPoint(x: 16.5, y: 40), controlPoint1: CGPoint(x: 5, y: 52), controlPoint2: CGPoint(x: 16.5, y: 50))
            p.addLine(to: CGPoint(x: 16.5, y: 12))
            p.addLine(to: CGPoint(x: 15, y: 9))
            p.close()
            c.saveGState()
            p.addClip()
            lin(c, [shc(0.04, 0.22, 0.09, 0.95), shc(0.22, 0.62, 0.3, 0.9), shc(0.03, 0.18, 0.08, 0.95)],
                [0, 0.4, 1], CGPoint(x: 5, y: 0), CGPoint(x: 35, y: 0))
            shc(0.93, 0.86, 0.68).setFill()
            c.fill(CGRect(x: 5, y: 72, width: 30, height: 24))
