            barrel.addLine(to: CGPoint(x: 146, y: 172))
            barrel.addLine(to: CGPoint(x: 94, y: 172))
            barrel.close()
            c.saveGState()
            barrel.addClip()
            lin(c, [shc(0.05, 0.06, 0.07), shc(0.38, 0.4, 0.45), shc(0.07, 0.08, 0.09)], [0, 0.45, 1],
                CGPoint(x: 94, y: 0), CGPoint(x: 146, y: 0))
            c.restoreGState()
